import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"-?\d+")


def _pop(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(n)]


def _plus(stack):
    b, a = _pop(stack, 2)
    stack.append(a + b)


def _minus(stack):
    b, a = _pop(stack, 2)
    stack.append(a - b)


def _times(stack):
    b, a = _pop(stack, 2)
    stack.append(a * b)


def _divide(stack):
    b, a = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    stack.append(a // b)


def _dup(stack):
    a = _pop(stack, 1)[0]
    stack.append(a)


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    b, a = _pop(stack, 2)
    stack.append(b)
    stack.append(a)


def _over(stack):
    b, a = _pop(stack, 2)
    stack.append(a)
    stack.append(b)
    stack.append(a)


_BUILTINS = {
    "+": _plus,
    "-": _minus,
    "*": _times,
    "/": _divide,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    stack = []
    words = {}

    for line in input_data:
        program = line.split()
        i = 0
        while i < len(program):
            token = program[i].lower()
            if token == ":":
                # Definition: ": name definition ;"
                if i + 1 >= len(program):
                    raise ValueError("illegal operation")
                name = program[i + 1].lower()
                if _NUMBER.fullmatch(name):
                    raise ValueError("illegal operation")
                body = []
                j = i + 2
                while j < len(program) and program[j].lower() != ";":
                    t = program[j].lower()
                    # User words are compiled against the definitions
                    # that exist at definition time.
                    if t in words:
                        body.extend(words[t])
                    else:
                        body.append(t)
                    j += 1
                if j >= len(program):
                    raise ValueError("illegal operation")
                words[name] = body
                i = j + 1
            elif _NUMBER.fullmatch(token):
                stack.append(int(token))
                i += 1
            elif token in words:
                # Splice the word's body in place so its tokens are
                # executed in order.
                program[i:i + 1] = words[token]
            elif token in _BUILTINS:
                _BUILTINS[token](stack)
                i += 1
            else:
                raise ValueError("undefined operation")

    return stack

